
/* /v66img:logo/ V66 游戏 Logo 注入（加载页 + 顶部栏 + 开场 title_screen） */
(function(){
  try{
    var V66_LOGO = "data:image/png;base64,";
    function v66_addStyle(css){
      var s = document.createElement("style");
      s.type = "text/css";
      try{ s.appendChild(document.createTextNode(css)); }catch(e){ s.innerHTML = css; }
      (document.head || document.documentElement).appendChild(s);
    }
    /* ---- 1) 全屏加载页 ---- */
    var splash = document.createElement("div");
    splash.id = "v66-splash";
    splash.style.cssText = "position:fixed;inset:0;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#0a0e16;transition:opacity .6s ease;";
    splash.innerHTML = '<img src="'+V66_LOGO+'" alt=""/><div class="v66-splash-title">艾尔达大陆 · 群雄割据</div><div class="v66-splash-sub">群雄逐鹿 · 乱世浮沉</div>';
    splash.onclick = function(){ try{ v66_killSplash(); }catch(e){} };
    document.documentElement.appendChild(splash);
    v66_addStyle(
      '#v66-splash img{width:220px;height:220px;border-radius:24px;box-shadow:0 0 60px rgba(120,40,30,.55);}'
      + '#v66-splash .v66-splash-title{margin-top:22px;font-family:"Noto Serif SC","STSong","SimSun",serif;font-size:30px;font-weight:700;letter-spacing:6px;color:#e8dcc0;text-shadow:0 0 24px rgba(200,120,60,.4);}'
      + '#v66-splash .v66-splash-sub{margin-top:10px;font-size:13px;letter-spacing:8px;color:rgba(232,220,192,.5);}'
      + '#v66-splash.fade{opacity:0;}'
    );
    function v66_killSplash(){
      try{ var el = document.getElementById("v66-splash"); if(el && el.parentNode){ el.parentNode.removeChild(el); } }catch(e){}
    }
    setTimeout(function(){ try{ var el = document.getElementById("v66-splash"); if(el) el.className = "fade"; }catch(e){} }, 1500);
    setTimeout(function(){ v66_killSplash(); }, 2300);
    /* ---- 2) 顶部栏小标 ---- */
    function v66_topLogo(){
      try{
        var tb = document.getElementById("topbar");
        if(!tb) return;
        var t = tb.querySelector(".title");
        if(!t) return;
        if(document.getElementById("v66-top-logo")) return;
        var im = document.createElement("img");
        im.id = "v66-top-logo";
        im.src = V66_LOGO;
        im.style.cssText = "width:22px;height:22px;border-radius:5px;vertical-align:-4px;margin-right:8px;";
        t.parentNode.insertBefore(im, t);
      }catch(e){}
    }
    /* ---- 3) title_screen 开场大图（经 v61 afterWrite 钩子） ---- */
    function v66_titleLogo(){
      try{
        var old = document.getElementById("v66-title-logo");
        if(old && old.parentNode) old.parentNode.removeChild(old);
        if(typeof curNode === "undefined" || curNode !== "title_screen") return;
        var st = document.getElementById("story");
        if(!st) return;
        var im = document.createElement("img");
        im.id = "v66-title-logo";
        im.src = V66_LOGO;
        im.alt = "艾尔达大陆 · 群雄割据";
        im.style.cssText = "display:block;width:150px;height:150px;border-radius:18px;margin:0 auto 18px;box-shadow:0 0 40px rgba(120,40,30,.5);";
        st.insertBefore(im, st.firstChild);
      }catch(e){}
    }
    if(typeof window.v61_registerAfterWrite === "function"){ try{ window.v61_registerAfterWrite(v66_titleLogo); }catch(e){} }
    var _rd = function(){ v66_topLogo(); };
    if(document.readyState === "loading"){ document.addEventListener("DOMContentLoaded", _rd); } else { _rd(); }
    var iv = setInterval(function(){
      if(document.getElementById("v66-top-logo")){ try{ clearInterval(iv); }catch(e){} return; }
      v66_topLogo();
    }, 3000);
  }catch(e){ try{ console.error("[v66logo]", e); }catch(_){} }
})();
